/**
 * 大模型文件的**分块并发下载**。
 *
 * 为什么需要它：GitHub Pages（以及其他不少静态托管）对**单条 TCP 连接**限速。
 * 2026-10-19 实测 `content/wugao-site-full-v20260923.glb`（33 MB）：
 *
 * | 并发连接数 | 聚合吞吐 | 33 MB 需要 |
 * |---|---|---|
 * | 1 | 37 KB/s | ≈ 15 分钟 |
 * | 2 | 67 KB/s | ≈ 8 分钟 |
 * | 4 | 140 KB/s | ≈ 4 分钟 |
 * | 8 | 247 KB/s | ≈ 2.2 分钟 |
 *
 * 也就是说瓶颈在**每条连接**（约 31 KB/s），而不是用户带宽 —— 现场反馈"网速并没有那么慢，
 * 但模型加载太慢"正是这个原因。`Accept-Ranges: bytes` 是 GitHub Pages 一直带上的响应头，
 * 所以这里用 Range 请求把同一个文件切成若干段并发拉，再拼回一个 ArrayBuffer 交给
 * `GLTFLoader.parse()`；任何一步不符合预期（不支持 Range、返回 200、分块失败）都返回
 * `null` / 抛错，由调用方退回原来的单请求 `loader.load()`。
 *
 * 刻意**总是**走分块路径（而不是"先单请求、慢了再换"）：HTTP 缓存对 206 响应是按段缓存的，
 * 两条路径来回切会让缓存完全失效；固定一条路径时，重复访问仍能命中同一批分段缓存。
 *
 * **2026-10-15 补的硬条件：响应带 `content-encoding` 就不能分块。**
 * 线上 GitHub Pages 给 `.glb` 开了 gzip：同一个文件
 *
 * ```
 * GET   （Accept-Encoding: gzip）→ 200  Content-Length: 5547976  Content-Encoding: gzip
 * Range bytes=0-11（同样请求头）  → 206  Content-Range: bytes 0-11/5547976  Content-Encoding: gzip
 * ```
 *
 * 也就是说 Range 的分母是**压缩后**的长度（真实 7,624,788），返回的 12 字节是 gzip 流的开头，
 * 根本不是 `glTF` 魔数 —— 照这个总长分配缓冲区再拼段，拼出来的必然是一份坏文件，
 * `GLTFLoader` 读最后一个 `bufferView` 时抛 `Invalid typed array length: 4`。
 * （浏览器对"带 gzip 的 206"还会整片报 `ERR_CONTENT_DECODING_FAILED`。）
 * 所以探测阶段只要看到 `content-encoding` 不是 identity，就直接放弃分块、退回单请求：
 * 单请求由浏览器按内容编码整包解压，字节一定是对的。
 */

import { glbDeclaredLengthFromBytes, glbIntegrityProblem, isGlbUrl } from './glbIntegrity';

/** 低于这个大小就不折腾了：小文件单请求更快，也没有限速问题。 */
export const CHUNKED_MIN_BYTES = 4 * 1024 * 1024;
/** 并发连接数。浏览器对同源 HTTP/1.1 一般允许 6 条，再多只会排队。 */
export const CHUNKED_CONCURRENCY = 6;

export interface ChunkedDownloadOptions {
  /** 进度回调，与 `XMLHttpRequest` 的语义一致：0–100 的整数百分比。 */
  onProgress?: (percent: number) => void;
  concurrency?: number;
  minBytes?: number;
  /** 便于单测注入。 */
  fetcher?: typeof fetch;
}

interface Probe {
  total: number;
}

/** 探测时顺便拿回文件开头这些字节：够读 GLB 头（魔数 + 声明总长）。 */
const PROBE_BYTES = 12;

/** 响应是否带内容编码（`gzip` / `br` / `deflate`…）。带编码时 Range 的字节与总长都不可信。 */
function hasContentEncoding(response: Response): string | null {
  const encoding = (response.headers.get('content-encoding') ?? '').trim().toLowerCase();
  return encoding && encoding !== 'identity' ? encoding : null;
}

/** 解析 `content-range: bytes 0-11/12345`；格式不对或总长不可用时返回 `null`。 */
function parseContentRange(value: string | null): { start: number; end: number; total: number } | null {
  const match = /^bytes\s+(\d+)-(\d+)\/(\d+)$/.exec((value ?? '').trim());
  if (!match) return null;
  const start = Number(match[1]);
  const end = Number(match[2]);
  const total = Number(match[3]);
  if (!Number.isFinite(start) || !Number.isFinite(end) || !Number.isFinite(total)) return null;
  if (total <= 0 || start > end || end >= total) return null;
  return { start, end, total };
}

/**
 * 用一小段 Range 请求探一次：既能确认服务端支持 Range，又能拿到文件总长。
 * 不支持（忽略 Range 返回 200、没有 content-range、跨域被拦）时返回 null。
 *
 * **GLB 会多一道交叉验证**：服务端报的总长必须等于文件头自己声明的
 * `declaredLength`。线上出现过服务端总长不可信（例如报的是压缩后长度）的情况，
 * 那时分块下载会按错误的总长分配缓冲区、拼出一份**短文件**，`GLTFLoader` 读最后一个
 * `bufferView` 时抛 `Invalid typed array length` —— 宁可不分块，也不能拼出这种字节。
 */
async function probe(fetcher: typeof fetch, url: string): Promise<Probe | null> {
  const response = await fetcher(url, { headers: { Range: `bytes=0-${PROBE_BYTES - 1}` } });
  if (response.status !== 206) {
    // 服务端忽略了 Range（200 会把整个文件吐出来）——立刻掐断，别白下 33MB。
    void response.body?.cancel().catch(() => {});
    return null;
  }
  const encoding = hasContentEncoding(response);
  if (encoding) {
    // 带 gzip/br 的 206：Range 的分母是压缩后长度，段字节也不是文件字节，拼起来必坏（见文件头注释）。
    void response.body?.cancel().catch(() => {});
    console.warn(`分块下载跳过：${url} 的响应带 content-encoding: ${encoding}，Range 字节与总长都不可信`);
    return null;
  }
  const range = parseContentRange(response.headers.get('content-range'));
  if (!range) {
    void response.body?.cancel().catch(() => {});
    return null;
  }
  let head: Uint8Array | null;
  try {
    head = new Uint8Array(await response.arrayBuffer());
  } catch {
    head = null;
  }
  if (head && isGlbUrl(url)) {
    const declared = glbDeclaredLengthFromBytes(head);
    if (declared !== null && declared !== range.total) {
      console.warn(`分块下载跳过：${url} 的服务端总长 ${range.total} 与 glTF 头声明 ${declared} 不一致`);
      return null;
    }
  }
  return { total: range.total };
}

/**
 * 下载单段；写入调用方给的目标缓冲区，边下边回报字节数。
 *
 * 除了"收满没有"，还检查响应头里的 `content-range` 与请求完全一致：代理/CDN 可能
 * 忽略或改写 Range（回 200、回别段、总长又是另一个数），那种字节拼进去就是垃圾。
 */
async function downloadRange(
  fetcher: typeof fetch,
  url: string,
  start: number,
  end: number,
  total: number,
  sink: Uint8Array,
  onBytes: (count: number) => void,
): Promise<void> {
  const response = await fetcher(url, { headers: { Range: `bytes=${start}-${end}` } });
  if (response.status !== 206 || !response.body) {
    void response.body?.cancel().catch(() => {});
    throw new Error(`分块下载失败：HTTP ${response.status}`);
  }
  const encoding = hasContentEncoding(response);
  if (encoding) {
    void response.body.cancel().catch(() => {});
    throw new Error(`分块下载失败：响应带 content-encoding: ${encoding}，段字节不可信`);
  }
  const range = parseContentRange(response.headers.get('content-range'));
  if (!range || range.start !== start || range.end !== end || range.total !== total) {
    void response.body.cancel().catch(() => {});
    throw new Error(`分块下载失败：服务端返回的范围与请求不一致（${response.headers.get('content-range') ?? '无 content-range'}）`);
  }
  const reader = response.body.getReader();
  let offset = start;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    if (!value?.length) continue;
    if (offset + value.length > end + 1) throw new Error('分块下载越界：服务端返回了多余的字节');
    sink.set(value, offset);
    offset += value.length;
    onBytes(value.length);
  }
  if (offset !== end + 1) throw new Error(`分块下载不完整：期望 ${end - start + 1} 字节，实际 ${offset - start}`);
}

/**
 * 分块并发下载；不适用或失败时返回 `null`，调用方应退回单请求下载。
 *
 * @returns 完整文件的 `ArrayBuffer`；不适用时 `null`（并非错误）。
 */
export async function fetchInChunks(url: string, options: ChunkedDownloadOptions = {}): Promise<ArrayBuffer | null> {
  const fetcher = options.fetcher ?? fetch;
  const concurrency = Math.max(2, options.concurrency ?? CHUNKED_CONCURRENCY);
  const minBytes = options.minBytes ?? CHUNKED_MIN_BYTES;

  // 省流模式（`navigator.connection.saveData`）下不要并发抢占带宽。
  const connection = typeof navigator === 'undefined'
    ? undefined
    : (navigator as Navigator & { connection?: { saveData?: boolean } }).connection;
  if (connection?.saveData) return null;

  const probed = await probe(fetcher, url);
  if (!probed) return null;
  const { total } = probed;
  if (total < minBytes) return null;

  const buffer = new Uint8Array(total);
  let received = 0;
  let reported = -1;
  const report = () => {
    const percent = Math.min(100, Math.round(received / total * 100));
    if (percent !== reported) {
      reported = percent;
      options.onProgress?.(percent);
    }
  };

  const chunkSize = Math.ceil(total / concurrency);
  const jobs: Array<{ start: number; end: number }> = [];
  for (let start = 0; start < total; start += chunkSize) {
    jobs.push({ start, end: Math.min(total - 1, start + chunkSize - 1) });
  }

  // 逐段带一次重试：弱网下单段偶发失败不该让整次加载退化回单连接。
  const runJob = async (job: { start: number; end: number }) => {
    for (let attempt = 0; attempt < 2; attempt += 1) {
      try {
        await downloadRange(fetcher, url, job.start, job.end, total, buffer, count => { received += count; report(); });
        return;
      } catch (error) {
        if (attempt === 1) throw error;
      }
    }
  };

  // 并发度受控：每次最多 concurrency 段同时在跑。
  let cursor = 0;
  const workers = Array.from({ length: Math.min(concurrency, jobs.length) }, async () => {
    for (;;) {
      const job = jobs[cursor];
      cursor += 1;
      if (!job) return;
      await runJob(job);
    }
  });
  await Promise.all(workers);
  // 拼完再按容器骨架验一次：服务端总长自洽、但字节仍可能因别的原因残缺。
  if (isGlbUrl(url)) {
    const problem = glbIntegrityProblem(buffer.buffer);
    if (problem) throw new Error(problem);
  }
  options.onProgress?.(100);
  return buffer.buffer;
}
