/**
 * GLB 容器完整性检查。
 *
 * **为什么要它**：现场（GitHub Pages + 手机）出现过
 * 「模型加载失败 / `Invalid typed array length: 4`」。这个报错不是 three.js 发的，而是 V8 在
 * **用越界的 byteOffset/length 造 TypedArray 视图**时抛的（`node -e "new Uint8Array(new ArrayBuffer(8), 6, 4)"`
 * 就能复现同一条消息）——也就是 `GLTFLoader` 拿到的 `ArrayBuffer` **比文件自己声明的长度短**：
 * JSON 块完好、BIN 块尾巴被截掉，读最后一个 `bufferView` 时就踩到了缓冲区外。
 *
 * 截断可能来自三处，都真实存在：
 *   ① 整包下载被网络/代理中断；
 *   ② 服务端对 `Range` 请求回的 `content-range` 里的总长不可信（等于压缩后长度等），
 *      `chunkedDownload` 按它 `new Uint8Array(total)` 分配缓冲区 → 拼出来的就是短文件；
 *   ③ **上一次中断留下的 Cache Storage 坏条目**——最恶劣：素材文件名带版本号，URL 永不变，
 *      于是坏字节每次访问都被命中、每次都失败，「重新加载」也救不回来。
 *
 * 因此每份字节在**从缓存读出来之后**和**交给 `GLTFLoader.parse()` 之前**都要过一遍这里；
 * 不合格就丢掉重取，绝不让截断的字节进入解析器。检查只看容器骨架（头部 + 分块表 + JSON 清单），
 * 不做几何/贴图级校验：几十 MB 的模型上它必须是 O(分块数)。
 */

const GLB_HEADER_BYTES = 12;
const CHUNK_HEADER_BYTES = 8;
const MAGIC = 0x46546c67; // 'glTF' 小端
const CHUNK_TYPE_JSON = 0x4e4f534a; // 'JSON'
const CHUNK_TYPE_BIN = 0x004e4942; // 'BIN\0'

/** GLB 里 BIN 块按 4 字节对齐，允许比 `buffers[0].byteLength` 多出 0–3 个填充字节。 */
const BIN_PADDING_MAX = 3;

interface Chunk {
  type: number;
  length: number;
  offset: number;
}

function chunkTypeName(type: number): string {
  const bytes = new Uint8Array(new Uint32Array([type]).buffer);
  return String.fromCharCode(...bytes).replace(/\0+$/, '') || '未知';
}

/**
 * 从**一小段文件开头字节**里读声明总长（`chunkedDownload` 的 1 次 Range 探测用：
 * 只拿回十几个字节，就能把服务端报的总长和文件头自己声明的长度对上）。
 *
 * @returns 不是 glTF 或以 `glTF` 开头但字节不够时返回 `null`。
 */
export function glbDeclaredLengthFromBytes(bytes: Uint8Array): number | null {
  if (bytes.byteLength < GLB_HEADER_BYTES) return null;
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  return view.getUint32(0, true) === MAGIC ? view.getUint32(8, true) : null;
}

/**
 * 文件头里声明的总长；连头都不完整时返回 `null`。仅用于日志与诊断。
 */
export function glbDeclaredLength(buffer: ArrayBuffer): number | null {
  return glbDeclaredLengthFromBytes(new Uint8Array(buffer));
}

/**
 * 检查 GLB 容器是否自洽。
 *
 * @returns 自洽时 `null`，否则返回一句能直接显示给用户/写进日志的中文原因。
 */
export function glbIntegrityProblem(buffer: ArrayBuffer): string | null {
  const byteLength = buffer.byteLength;
  if (byteLength < GLB_HEADER_BYTES) {
    return `模型文件不完整：只有 ${byteLength} 字节，连 12 字节的 GLB 头都没有`;
  }

  const view = new DataView(buffer);
  const magic = view.getUint32(0, true);
  if (magic !== MAGIC) {
    return `模型文件损坏：文件头不是 glTF（magic=0x${magic.toString(16)}）`;
  }

  const version = view.getUint32(4, true);
  if (version !== 2) {
    return `模型文件版本不支持：glTF ${version}（只支持 2）`;
  }

  const declared = view.getUint32(8, true);
  if (declared !== byteLength) {
    // 短了说明被截断；长了说明读到的字节比声明的还多（同样不敢用）。
    const hint = declared > byteLength ? '下载或缓存里的字节被截断' : '字节数与文件头声明不一致';
    return `模型文件不完整（${hint}）：文件头声明 ${declared} 字节，实际 ${byteLength} 字节`;
  }

  const chunks: Chunk[] = [];
  let offset = GLB_HEADER_BYTES;
  while (offset < byteLength) {
    if (offset + CHUNK_HEADER_BYTES > byteLength) {
      return `模型文件不完整：在 ${offset} 字节处缺少分块头`;
    }
    const length = view.getUint32(offset, true);
    const type = view.getUint32(offset + 4, true);
    if (offset + CHUNK_HEADER_BYTES + length > byteLength) {
      return `模型文件不完整：${chunkTypeName(type)} 块声明 ${length} 字节，但只剩 ${byteLength - offset - CHUNK_HEADER_BYTES} 字节`;
    }
    chunks.push({ type, length, offset: offset + CHUNK_HEADER_BYTES });
    offset += CHUNK_HEADER_BYTES + length;
  }

  const json = chunks.find(chunk => chunk.type === CHUNK_TYPE_JSON);
  if (!json) return '模型文件损坏：缺少 JSON 清单块';

  let declaredBufferLength: number | null = null;
  try {
    const text = new TextDecoder().decode(new Uint8Array(buffer, json.offset, json.length));
    const document = JSON.parse(text) as { buffers?: Array<{ byteLength?: number }> };
    const first = document.buffers?.[0]?.byteLength;
    if (typeof first === 'number' && Number.isFinite(first)) declaredBufferLength = first;
  } catch {
    return '模型文件损坏：JSON 清单块无法解析';
  }

  const bin = chunks.find(chunk => chunk.type === CHUNK_TYPE_BIN);
  if (declaredBufferLength !== null && declaredBufferLength > 0) {
    if (!bin) return '模型文件损坏：清单里引用了二进制数据，但没有 BIN 块';
    if (bin.length < declaredBufferLength) {
      return `模型文件不完整：二进制数据需要 ${declaredBufferLength} 字节，实际只有 ${bin.length} 字节`;
    }
    if (bin.length - declaredBufferLength > BIN_PADDING_MAX) {
      return `模型文件损坏：二进制块比清单多出 ${bin.length - declaredBufferLength} 字节`;
    }
  }

  return null;
}

/** 只对 `.glb` 做容器检查；其它格式（FBX/OBJ/STL）交给各自的解析器。 */
export function isGlbUrl(url: string): boolean {
  return /\.glb(?:$|[?#])/i.test(url);
}
