import * as THREE from 'three';
import { DRACOLoader } from 'three/examples/jsm/loaders/DRACOLoader.js';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader.js';
import { GLTFLoader, type GLTF } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader.js';
import { STLLoader } from 'three/examples/jsm/loaders/STLLoader.js';
import { MeshoptDecoder } from 'three/examples/jsm/libs/meshopt_decoder.module.js';
import { resolveAssetUrl } from '../../config/loadConfig';
import { deleteCachedAsset, fetchCachedBuffer, isAssetCacheAvailable, readCachedBuffer, writeCachedBuffer } from '../../shared/assetCache';
import { fetchInChunks } from '../../shared/chunkedDownload';
import { pickModelUrl } from '../../shared/deviceTier';
import { glbIntegrityProblem, isGlbUrl } from '../../shared/glbIntegrity';
import type { DeviceConfig, DevicePartConfig } from '../../config/schema';
import { bindConfiguredParts, getObjectsBounds, type PartBindingIssue } from './partBindings';
import type { DevicePartRuntime } from './deviceSceneState';

export interface LoadedDeviceModel {
  root: THREE.Object3D;
  parts: Map<string, DevicePartRuntime>;
  issues: PartBindingIssue[];
}

function cloneMeshMaterials(mesh: THREE.Mesh) {
  mesh.material = Array.isArray(mesh.material)
    ? mesh.material.map(material => material.clone())
    : mesh.material.clone();
}

export function registerDeviceParts(root: THREE.Object3D, parts: DevicePartConfig[]) {
  const bound = bindConfiguredParts(root, parts);
  const runtimes = new Map<string, DevicePartRuntime>();

  for (const [id, binding] of bound.bindings) {
    const meshes = [...binding.meshes];
    meshes.forEach(mesh => {
      cloneMeshMaterials(mesh);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
    });
    // Explosion directions and packing offsets are expressed in world space, but
    // they are applied to `object.position`, which lives in the parent's frame.
    // FBX-derived models sit under a −90° X pre-rotation, so cache each anchor's
    // world rotation to convert before assigning.
    binding.objects.forEach(object => object.updateWorldMatrix(true, false));
    const rootRotations = binding.objects.map(object => object.getWorldQuaternion(new THREE.Quaternion()));
    runtimes.set(id, {
      id,
      config: binding.part,
      roots: binding.objects,
      meshes,
      origins: binding.origins,
      originalVisibility: binding.originalVisibility ?? binding.objects.map(object => object.visible),
      bounds: getObjectsBounds(binding.objects),
      rootRotations,
    });
  }

  return { parts: runtimes, issues: bound.issues };
}

const PROCEDURAL_ORIGINS: Record<string, [number, number, number]> = {
  base: [0, 0.25, 0], body: [0, 2, 0], upper: [0, 4, 0], top: [0, 5.1, 0],
};

function createProceduralPart(part: DevicePartConfig) {
  const group = new THREE.Group();
  group.name = `part-${part.id}`;
  group.position.fromArray(PROCEDURAL_ORIGINS[part.id] ?? [0, 0, 0]);
  const material = new THREE.MeshStandardMaterial({ color: ['#a9b8bb', '#83aaa8', '#bc9084', '#d3ad70'][part.level - 1] ?? '#9baeb0', metalness: 0.32, roughness: 0.48 });
  const geometries: Array<{ geometry: THREE.BufferGeometry; y?: number }> = [];
  if (part.id === 'base') geometries.push({ geometry: new THREE.BoxGeometry(3.2, 0.5, 2.2) });
  else if (part.id === 'body') {
    geometries.push({ geometry: new THREE.CylinderGeometry(1.2, 1.35, 3, 40) });
    for (const y of [-1.3, -0.65, 0, 0.65, 1.3]) geometries.push({ geometry: new THREE.TorusGeometry(1.42, 0.11, 12, 40), y });
  } else if (part.id === 'upper') geometries.push({ geometry: new THREE.CylinderGeometry(0.9, 1.05, 1, 36) });
  else if (part.id === 'top') geometries.push({ geometry: new THREE.SphereGeometry(0.75, 32, 20) });
  else geometries.push({ geometry: new THREE.BoxGeometry(2, 1.5, 2) });
  for (const item of geometries) {
    const mesh = new THREE.Mesh(item.geometry, material);
    if (item.y !== undefined) mesh.position.y = item.y;
    group.add(mesh);
  }
  return group;
}

export function createProceduralDeviceModel(device: DeviceConfig): LoadedDeviceModel {
  const root = new THREE.Group();
  root.name = 'device-model';
  root.position.set(0, -2.7, 0);
  for (const part of device.parts) root.add(createProceduralPart(part));
  const registered = registerDeviceParts(root, device.parts);
  return { root, ...registered };
}

export interface LoadModelOptions {
  onProgress?(percent: number): void;
}

/** @deprecated 用 `LoadModelOptions`；保留旧名以免外部引用失效。 */
export type LoadDeviceModelOptions = LoadModelOptions;

/** 模型文件相对路径（`.glb` 里内嵌贴图以外的外部资源按它解析）。 */
function modelBasePath(url: string): string {
  try {
    return new URL('.', new URL(url, window.location.href)).href;
  } catch {
    return '';
  }
}

function parseGltf(loader: GLTFLoader, buffer: ArrayBuffer, url: string): Promise<THREE.Object3D> {
  // 解析前再过一次容器校验：宁可在这里报"文件不完整"，也不要把截断的字节喂进 GLTFLoader
  // （那种情况下解析器会抛出 `Invalid typed array length: 4` 这类看不出所以然的 RangeError）。
  const problem = isGlbUrl(url) ? glbIntegrityProblem(buffer) : null;
  if (problem) return Promise.reject(new Error(problem));
  return new Promise<GLTF>((resolve, reject) => {
    loader.parse(buffer, modelBasePath(url), resolve, reject);
  }).then(gltf => gltf.scene);
}

/**
 * 走"**持久缓存优先** → 分块并发下载 → 单请求整包 → three 自带加载器"四层，逐层都校验字节。
 *
 * 顺序（见 `shared/assetCache.ts`）：
 *   ① 缓存命中 → 直接用上次存下的整份字节，**一个请求都不发**（"避免重复下载"）；
 *   ② 未命中 → 分块并发（GitHub Pages 单连接只有约 31 KB/s，33 MB 的场地模型单请求要十几分钟；
 *      6 段并发实测约 6 倍聚合带宽），拼回整份后**回填缓存**，下次就走到 ①；
 *   ③ 分块不适用（小文件 / 省流模式 / 服务端不支持 Range）或校验不过 → 单请求整包 + 校验；
 *   ④ 仍然失败 → 退回 three 自己的加载器（网络与进度由它处理）。
 *
 * 每一层取到的字节都过 `glbIntegrityProblem`：缓存里不合格的条目会被**删掉**（否则 URL 带版本号、
 * 那份坏字节会被永久命中），网络字节不合格则丢弃并走下一层。
 */
async function loadGltf(
  loader: GLTFLoader,
  url: string,
  onProgress?: (percent: number) => void,
): Promise<THREE.Object3D> {
  const validate = (buffer: ArrayBuffer) => (isGlbUrl(url) ? glbIntegrityProblem(buffer) : null);
  const problems: string[] = [];

  const cached = await readCachedBuffer(url);
  if (cached) {
    const problem = validate(cached);
    if (!problem) {
      onProgress?.(100);
      return parseGltf(loader, cached, url);
    }
    // 坏缓存条目必须删掉：素材文件名带版本号，留着它每次访问都会命中并再次失败。
    await deleteCachedAsset(url);
    problems.push(problem);
    console.warn(`丢弃损坏的模型缓存：${url}（${problem}）`);
  }

  try {
    const buffer = await fetchInChunks(url, { onProgress });
    if (buffer) {
      const problem = validate(buffer);
      if (problem) {
        problems.push(problem);
        console.warn(`丢弃损坏的分块下载结果：${url}（${problem}）`);
      } else {
        // 回填持久缓存：等它写完再解析，保证"这次看过 = 下次免下载"。
        await writeCachedBuffer(url, buffer, 'model/gltf-binary');
        return await parseGltf(loader, buffer, url);
      }
    }
  } catch (error) {
    problems.push(error instanceof Error ? error.message : String(error));
  }

  // `reload: true` 绕开浏览器 HTTP 缓存：坏字节也可能藏在 HTTP 缓存里。
  const whole = await fetchCachedBuffer(url, { onProgress, validate, reload: true });
  if (whole) {
    try {
      return await parseGltf(loader, whole, url);
    } catch (error) {
      problems.push(error instanceof Error ? error.message : String(error));
    }
  }

  return new Promise<THREE.Object3D>((resolve, reject) => {
    const progress = (event: ProgressEvent<EventTarget>) => {
      if (event.lengthComputable && event.total > 0) onProgress?.(Math.round(event.loaded / event.total * 100));
    };
    loader.load(url, gltf => resolve(gltf.scene), progress, error => {
      // 前几层如果看到过"字节不完整"，那就是最贴近真相的原因，优先报它。
      const integrity = problems.find(text => text.includes('不完整') || text.includes('损坏'));
      const fallback = error instanceof Error ? error.message : '';
      reject(new Error(integrity ?? problems[0] ?? fallback ?? '模型加载失败'));
    });
  });
}

/** 把整份字节包成 STL 的设备根（与旧单请求路径同一个包装）。 */
function stlRootFromGeometry(geometry: THREE.BufferGeometry): THREE.Object3D {
  const root = new THREE.Group();
  root.name = 'stl-model';
  root.add(new THREE.Mesh(geometry, new THREE.MeshStandardMaterial({ color: '#cbd5db', metalness: 0.15, roughness: 0.6 })));
  return root;
}

/**
 * 缓存优先地取整份模型字节并解析（FBX/OBJ/STL 用）。
 * 缓存不可用或取不到字节时返回 `null`，调用方应退回各自的 `loader.load()` 单请求路径。
 */
async function loadModelFromCache(
  source: { kind: 'fbx' | 'obj' | 'stl' },
  url: string,
  onProgress?: (percent: number) => void,
): Promise<THREE.Object3D | null> {
  if (!isAssetCacheAvailable()) return null;
  const buffer = await fetchCachedBuffer(url, { onProgress });
  if (!buffer) return null;
  if (source.kind === 'fbx') return new FBXLoader().parse(buffer, modelBasePath(url));
  if (source.kind === 'obj') return new OBJLoader().parse(new TextDecoder().decode(buffer));
  return stlRootFromGeometry(new STLLoader().parse(buffer));
}

/**
 * 按来源加载模型文件（不含部件绑定）。设备页与场地页共用同一套加载器接线，
 * 因此 Draco / meshopt 解码器、FBX/OBJ/STL 支持只在这里配置一次。
 */
export function loadModelSource(
  source: Exclude<DeviceConfig['source'], { kind: 'procedural' }>,
  { onProgress }: LoadModelOptions = {},
): Promise<THREE.Object3D> {
  // 手机/平板走低配模型（面数约 1/4~1/5），桌面走完整模型；`?quality=high|low` 可强制。
  const url = resolveAssetUrl(pickModelUrl(source));
  const progress = (event: ProgressEvent<EventTarget>) => {
    if (event.lengthComputable && event.total > 0) onProgress?.(Math.round(event.loaded / event.total * 100));
  };

  if (source.kind === 'gltf') {
    return new Promise((resolve, reject) => {
      const loader = new GLTFLoader();
      const draco = new DRACOLoader();
      draco.setDecoderPath(`${import.meta.env.BASE_URL}draco/`);
      loader.setDRACOLoader(draco);
      loader.setMeshoptDecoder(MeshoptDecoder);
      void loadGltf(loader, url, onProgress)
        .then(scene => { draco.dispose(); resolve(scene); })
        .catch(error => { draco.dispose(); reject(error); });
    });
  }

  // FBX / OBJ / STL：有持久缓存就走"整份字节 + parse"，否则保持原来的单请求加载路径一字不动。
  return loadModelFromCache(source, url, onProgress).then(root => {
    if (root) return root;
    if (source.kind === 'fbx') return new Promise<THREE.Object3D>((resolve, reject) => { new FBXLoader().load(url, resolve, progress, reject); });
    if (source.kind === 'obj') return new Promise<THREE.Object3D>((resolve, reject) => { new OBJLoader().load(url, resolve, progress, reject); });
    return new Promise<THREE.Object3D>((resolve, reject) => { new STLLoader().load(url, geometry => resolve(stlRootFromGeometry(geometry)), progress, reject); });
  });
}

export function loadDeviceModel(device: DeviceConfig, { onProgress }: LoadDeviceModelOptions = {}): Promise<LoadedDeviceModel> {
  onProgress?.(0);
  if (device.source.kind === 'procedural') {
    const model = createProceduralDeviceModel(device);
    onProgress?.(100);
    return Promise.resolve(model);
  }

  return loadModelSource(device.source, { onProgress }).then(root => {
    onProgress?.(100);
    return { root, ...registerDeviceParts(root, device.parts) };
  });
}

export function disposeLoadedDeviceModel(model: LoadedDeviceModel) {
  disposeModelRoot(model.root);
}

/** 释放一棵模型子树占用的几何/材质/贴图（设备页与场地页共用）。 */
export function disposeModelRoot(root: THREE.Object3D) {
  const geometries = new Set<object>();
  const materials = new Set<THREE.Material>();
  const textures = new Set<THREE.Texture>();
  const rememberTexture = (value: unknown) => {
    if (value instanceof THREE.Texture) textures.add(value);
    else if (Array.isArray(value)) value.forEach(rememberTexture);
  };
  root.traverse(object => {
    const mesh = object as THREE.Mesh;
    if (!mesh.isMesh) return;
    if (mesh.geometry && !geometries.has(mesh.geometry)) {
      geometries.add(mesh.geometry);
      mesh.geometry.dispose();
    }
    const meshMaterials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
    for (const material of meshMaterials) {
      if (material && !materials.has(material)) {
        materials.add(material);
        Object.values(material).forEach(rememberTexture);
        if ('uniforms' in material && material.uniforms && typeof material.uniforms === 'object') {
          Object.values(material.uniforms as Record<string, { value?: unknown }>).forEach(uniform => rememberTexture(uniform?.value));
        }
        material.dispose();
      }
    }
  });
  textures.forEach(texture => texture.dispose());
}
